import React, { useState } from 'react';
import { Modal, Button, Form } from 'react-bootstrap';
import api from './Axios';

const BookingModal = ({ show, handleClose, professionalId, refreshBookings }) => {
  const [bookingDateTime, setBookingDateTime] = useState('');
  const [loading, setLoading] = useState(false);

  const handleBookingSubmit = async () => {
    if (!bookingDateTime) {
      alert("Please select a booking date and time.");
      return;
    }

    const selectedDate = new Date(bookingDateTime);
    const selectedHour = selectedDate.getHours();
    const selectedDay = selectedDate.getDay(); // Sunday = 0

    if (selectedDay === 0) {
      alert("Booking on Sundays is not allowed.");
      return;
    }

    if (selectedHour < 10 || selectedHour >= 17) {
      alert("Please select a time between 10:00 AM and 5:00 PM.");
      return;
    }

    setLoading(true);
    try {
      const token = localStorage.getItem("authToken");
      const payload = { professionalId, bookingDateTime };
      const response = await api.post("http://localhost:6543/api/bookings", payload, {
        headers: {
          "Content-Type": "application/json",
          "Authorization": "Bearer " + token
        }
      });
      if (response.status === 200 || response.status === 201) {
        alert("Booking created successfully. Status: PENDING.");
        handleClose();
        if (refreshBookings) refreshBookings();
      } else {
        alert("Error creating booking.");
      }
    } catch (error) {
      console.error("Error creating booking:", error);
      alert("Error creating booking: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDateTimeChange = (e) => {
    const selectedDate = new Date(e.target.value);
    const day = selectedDate.getDay();

    // Prevent Sunday selection
    if (day === 0) {
      alert("Booking on Sundays is not allowed.");
      setBookingDateTime('');
      return;
    }

    setBookingDateTime(e.target.value);
  };

  // Define min and max time for the day (without setting the date)
  const getMinTime = () => {
    const today = new Date();
    today.setHours(10, 0, 0, 0);
    return today.toISOString().slice(11, 16); // Only extract time part
  };

  const getMaxTime = () => {
    const today = new Date();
    today.setHours(17, 0, 0, 0);
    return today.toISOString().slice(11, 16); // Only extract time part
  };

  return (
    <Modal show={show} onHide={handleClose} centered>
      <Modal.Header closeButton>
        <Modal.Title>Book Professional</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <Form>
          <Form.Group controlId="bookingDateTime">
            <Form.Label>Select Date and Time</Form.Label>
            <Form.Control 
              type="datetime-local"
              value={bookingDateTime}
              onChange={handleDateTimeChange}
              min={`${new Date().toISOString().slice(0, 10)}T${getMinTime()}`} // Set min time for today
              max={`${new Date().toISOString().slice(0, 10)}T${getMaxTime()}`} // Set max time for today
            />
          </Form.Group>
        </Form>
      </Modal.Body>
      <Modal.Footer>
        <Button variant="secondary" onClick={handleClose}>Cancel</Button>
        <Button variant="primary" onClick={handleBookingSubmit} disabled={loading}>
          {loading ? "Booking..." : "Confirm Booking"}
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

export default BookingModal;
